def minDeletions(s: str) -> int:
    from collections import Counter
    counts = Counter(s)
    seen = set()
    deletions = 0
    for freq in counts.values():
        while freq > 0 and freq in seen:
            freq -= 1
            deletions += 1
        if freq > 0:
            seen.add(freq)
    return deletions

